package vision

import (
	"encoding/base64"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"

	"github.com/go-rod/rod/lib/proto"
)

// #301 PDF text slice: a PDF that landed in the session's governed file
// area reads back as bounded plain text. The fixture PDF is generated by
// Chrome's own print-to-PDF so the extraction covers real-world PDFs.
func TestPDFTextExtractionFromSessionFile(t *testing.T) {
	if os.Getenv("UIAI_INPUT_TESTS") == "" {
		t.Skip("set UIAI_INPUT_TESTS=1 for browser PDF regression")
	}
	site := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		fmt.Fprintf(w, `<!doctype html><html><body>
		<h1>Engine PDF Probe</h1>
		<p>The invoice total is forty-two dollars.</p>
		</body></html>`)
	}))
	defer site.Close()

	pool, err := NewPoolWithConfig(PoolConfig{MaxPages: 1, AllowPrivateURLs: true})
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Close()
	sm := NewSessionManager(pool)
	defer sm.CloseAll()

	session, _, err := sm.Open(site.URL, 640, 480)
	if err != nil {
		t.Fatalf("open: %v", err)
	}

	// Generate a real PDF from the page through Chrome's print-to-PDF.
	result, err := proto.PagePrintToPDF{PrintBackground: true}.Call(session.page)
	if err != nil {
		t.Fatalf("print to PDF: %v", err)
	}
	if len(result.Data) == 0 {
		t.Fatal("print to PDF returned no bytes")
	}
	if _, err := session.UploadFile("#missing", "probe.pdf", base64.StdEncoding.EncodeToString(result.Data)); err == nil {
		t.Fatal("expected upload to a missing input to fail; writing file directly instead")
	}

	// Write the PDF into the governed file area through the upload path's
	// directory by using the downloads surface: seed via a second input on
	// the fixture — simpler: write directly through UploadFile's governed
	// area by uploading to a real file input. Extend the fixture is complex;
	// instead assert extraction on the bytes via the session file route by
	// writing through UploadFile against a file input added to the page.
	if _, err := session.page.Eval(`() => { const i = document.createElement('input'); i.type = 'file'; i.id = 'pdf-slot'; document.body.appendChild(i); return 'added'; }`); err != nil {
		t.Fatalf("add file input: %v", err)
	}
	snap, err := session.UploadFile("#pdf-slot", "probe.pdf", base64.StdEncoding.EncodeToString(result.Data))
	if err != nil {
		t.Fatalf("upload pdf: %v", err)
	}
	if snap == nil || snap.Size == 0 {
		t.Fatal("upload must return a capture")
	}

	text, err := session.DownloadFileText("probe.pdf")
	if err != nil {
		t.Fatalf("pdf text: %v", err)
	}
	if !strings.Contains(text, "Engine PDF Probe") || !strings.Contains(text, "forty-two dollars") {
		t.Fatalf("extracted text lost the fixture content: %.200q", text)
	}

	// Non-PDF files are refused with a typed error.
	if _, err := session.DownloadFileText("definitely-not-a-pdf.txt"); err == nil {
		t.Fatal("text extraction must refuse non-PDF names")
	}
}
